pub(super) fn lookup_cjk(codepoint: u32) -> Option<&'static [u8; 32]> {
    let slice = CJK_FONT;
    let mut lo = 0usize;
    let mut hi = slice.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        let (key, _) = &slice[mid];
        if *key == codepoint {
            return Some(&slice[mid].1);
        } else if *key < codepoint {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    None
}